function suggestOnType(products: string[], typed: string): string[][] {
  const sorted = [...products].sort();
  const out: string[][] = [];
  for (let i = 1; i <= typed.length; i++) {
    const prefix = typed.slice(0, i);
    const row: string[] = [];
    for (const p of sorted) {
      if (p.startsWith(prefix)) { row.push(p); if (row.length === 3) break; }
    }
    out.push(row);
  }
  return out;
}

