  const root = new TrieNode();
  for (const word of [...products].sort()) {
    let node = root;
    for (const ch of word) {
      let next = node.kids.get(ch);
      if (!next) { next = new TrieNode(); node.kids.set(ch, next); }
      node = next;
      if (node.top.length < 3) node.top.push(word); // sorted insert: first three are the smallest
    }
